import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_host_tensor","description":"","frontmatter":{},"headers":[],"relativePath":"api/host-tensor/handl_host_tensor/handl_host_tensor.md","filePath":"api/host-tensor/handl_host_tensor/handl_host_tensor.md"}`),a={name:`api/host-tensor/handl_host_tensor/handl_host_tensor.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_host_tensor</strong></p><h1 id="module-handl-host-tensor" tabindex="-1">Module: handl_host_tensor <a class="header-anchor" href="#module-handl-host-tensor" aria-label="Permalink to “Module: handl_host_tensor”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#ops"><code>ops</code></a> - Rust <code>Function</code> impls for the <code>tensor</code> module — the handls (handlers)</li></ul><p><strong>Constants</strong></p><ul><li><a href="#tensor-hnl"><code>TENSOR_HNL</code></a> - The handl source declaring the <code>tensor</code> interface.</li></ul><hr><h2 id="handl-host-tensor-tensor-hnl" tabindex="-1">handl_host_tensor::TENSOR_HNL <a class="header-anchor" href="#handl-host-tensor-tensor-hnl" aria-label="Permalink to “handl_host_tensor::TENSOR_HNL”">​</a></h2><p><em>Constant</em>: <code>&amp;str</code></p><p>The handl source declaring the <code>tensor</code> interface.</p><h2 id="module-ops" tabindex="-1">Module: ops <a class="header-anchor" href="#module-ops" aria-label="Permalink to “Module: ops”">​</a></h2><p>Rust <code>Function</code> impls for the <code>tensor</code> module — the handls (handlers) for the <code>op</code>/<code>handle</code> declarations in <code>src/index.hnl</code>.</p><p>All 28 functions are FFI atoms: a tensor has no literal syntax and no eval-vocabulary constructor, so construction, projection, and algebra cannot be expressed as pure handl arrows. The impls here are the host-side half runtimes compose: a consumer registers them in an <a href="./handl_plugin_lib_handl::OpRegistry.html"><code>OpRegistry</code></a> (via [<code>tensor_op_registry</code>]) and wires them onto a <code>HandlModule</code> with <code>with_ops(TENSOR_OPS, …)</code>, after which <code>.hnl</code> <code>tensor.*</code> calls dispatch through the module chain into these impls.</p><h2 id="layout-the-module-map-mirrors-lib-tensor-s-spec-files-1-1" tabindex="-1">Layout (the module map mirrors lib-tensor&#39;s spec files 1:1) <a class="header-anchor" href="#layout-the-module-map-mirrors-lib-tensor-s-spec-files-1-1" aria-label="Permalink to “Layout (the module map mirrors lib-tensor&#39;s spec files 1:1)”">​</a></h2><table tabindex="0"><thead><tr><th>file</th><th>ops</th><th>spec</th></tr></thead><tbody><tr><td>[<code>codec</code>]</td><td>the wire codec + <code>zeros</code>/<code>ones</code>/<code>from_list</code>/<code>to_list</code>/<code>shape</code></td><td><code>codec.hnl</code></td></tr><tr><td>[<code>elementwise</code>]</td><td><code>add</code>/<code>mul</code>/<code>sub</code>/<code>div</code> + their <code>*_backward</code> adjoints</td><td><code>elementwise.hnl</code></td></tr><tr><td>[<code>matmul</code>]</td><td><code>matmul</code> (rank-2/3, batch broadcast) + <code>matmul_backward</code></td><td><code>matmul.hnl</code></td></tr><tr><td>[<code>conv</code>]</td><td><code>conv2d</code>, <code>max_pool</code> + their <code>*_backward</code> (NCHW)</td><td><code>conv.hnl</code></td></tr><tr><td>[<code>norm</code>]</td><td><code>batch_norm</code>, <code>batch_norm_backward</code></td><td><code>norm.hnl</code></td></tr><tr><td>[<code>shape_ops</code>]</td><td><code>reshape</code>, <code>transpose</code>, <code>concat</code> + their <code>*_backward</code></td><td><code>shape_ops.hnl</code></td></tr><tr><td>[<code>derive</code>]</td><td><code>derive</code> + <code>DERIV_PAIRS</code> (11 pairs)</td><td><code>norm.hnl</code>&#39;s <code>derive</code></td></tr></tbody></table><h2 id="the-tensor-value" tabindex="-1">The tensor value <a class="header-anchor" href="#the-tensor-value" aria-label="Permalink to “The tensor value”">​</a></h2><p>Tensors cross the <code>Function</code> boundary as <code>{&quot;__tensor__&quot;: {&quot;shape&quot;: [d, ...], &quot;data&quot;: [x, ...], &quot;dtype&quot;: &quot;f64&quot;}}</code> — a tagged plain object in the style of <code>{&quot;__bytes__&quot;: [n, ...]}</code> (ADR-0083 §2.1). <code>shape</code> is the extent per axis (rank = <code>shape.len()</code>), <code>data</code> the flat row-major payload (<code>data.len() == product(shape)</code>), <code>dtype</code> the element type — optional on decode, <code>&quot;f64&quot;</code> the only value accepted for now. Engines with no <code>Tensor</code> scalar see an ordinary object; engines with the kernel <code>TaggedValue::Tensor</code> decode the tag at the <code>call_host</code> boundary and carry the tensor opaquely.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};